var aiUi=require("$:/plugins/huwiki/ai/i18n.js");
/*\
title: $:/plugins/huwiki/ai/image-replies.js
type: application/javascript
module-type: library

Image replies: bounded previews, existing HUWiki AV storage, reference tiddlers.
\*/
(function(){
"use strict";
var MAX_BASE64=16*1024*1024;
var avCache=new Map(),avLoads=new Map();
function cacheImage(fileId,image){avCache.set(fileId,dataUrl(image));while(avCache.size>10)avCache.delete(avCache.keys().next().value);}
function loadAvImage(wiki,reference){
  var id=reference.fileId;if(avCache.has(id))return Promise.resolve(avCache.get(id));if(avLoads.has(id))return avLoads.get(id);
  var pending=rpc(wiki,'huGetAvPlayback',[reference.title]).then(function(reply){
    if(reply.id!==id)throw Error(aiUi.text('Billedreferencen er ændret. Genindlæs tiddleren.'));
    var image={mimeType:reply.mimeType,data:reply.base64};
    if(image.mimeType==='image/svg+xml')image.data=decodeURIComponent(escape(atob(image.data)));
    cacheImage(id,image);return avCache.get(id);
  });
  avLoads.set(id,pending);return pending.then(function(url){avLoads.delete(id);return url;},function(e){avLoads.delete(id);throw e;});
}
function safeSvg(value){
  var s=String(value||'').trim();
  if(s.length>200000||!/^<svg\b[^>]*>[\s\S]*<\/svg\s*>$/i.test(s))return '';
  // Deliberately accept inert vector graphics only. No external loads or active XML.
  if(/<!|<\?|\bon[a-z]+\s*=|\bstyle\s*=|\b(?:href|src)\s*=|\burl\s*\(|&#|&(?!(?:amp|lt|gt|quot|apos);)/i.test(s))return '';
  var allowed=/^(?:svg|g|path|rect|circle|ellipse|line|polyline|polygon|title|desc|defs|linearGradient|radialGradient|stop|clipPath|mask|text|tspan)$/i;
  var tags=s.match(/<[^>]*>/g)||[],depth=[],valid=true;
  tags.forEach(function(tag){var m=tag.match(/^<(\/)?([A-Za-z][A-Za-z0-9]*)(\s[^<>]*|\s*)>$/);if(!m||!allowed.test(m[2])){valid=false;return;}
    if(m[1]){if(depth.pop()!==m[2])valid=false;}else if(!/\/\s*>$/.test(tag))depth.push(m[2]);
  });
  return valid&&!depth.length?s:'';
}
function validateImage(image){
  if(!image||typeof image!=='object')throw Error(aiUi.text('Billedsvaret mangler.'));
  var mime=String(image.mimeType||'').toLowerCase(),data=String(image.data||'');
  if(mime==='image/svg+xml'){
    var svg=safeSvg(data);if(!svg)throw Error(aiUi.text('SVG indeholder ikke understøttet eller aktivt indhold. Koden kan stadig gemmes som tekst.'));
    return {mimeType:mime,data:svg};
  }
  if(['image/png','image/jpeg','image/webp'].indexOf(mime)<0||!data||data.length>MAX_BASE64||data.length%4||!/^[A-Za-z0-9+/]+={0,2}$/.test(data))throw Error(aiUi.text('Billedsvaret har et ugyldigt format eller er for stort.'));
  if((mime==='image/png'&&!/^iVBORw0KGgo/.test(data))||(mime==='image/jpeg'&&!/^\/9j\//.test(data))||(mime==='image/webp'&&!/^UklGR/.test(data)))throw Error(aiUi.text('Billeddata passer ikke til formatet.'));
  return {mimeType:mime,data:data};
}
function svgImages(text){var matches=String(text||'').match(/<svg\b[\s\S]*?<\/svg\s*>/gi)||[];return matches.slice(0,2).map(function(s){return safeSvg(s);}).filter(Boolean).map(function(s){return {mimeType:'image/svg+xml',data:s};});}
function dataUrl(image){var im=validateImage(image);return im.mimeType==='image/svg+xml'?'data:'+im.mimeType+';charset=utf-8,'+encodeURIComponent(im.data):'data:'+im.mimeType+';base64,'+im.data;}
function extension(mime){return {'image/svg+xml':'svg','image/png':'png','image/jpeg':'jpg','image/webp':'webp'}[mime]||'';}
function references(message){try{var a=JSON.parse(message.imageRefs||'[]');return Array.isArray(a)?a.map(function(r,i){return r&&Object.assign({index:i},r);}).filter(function(r){return r&&typeof r.title==='string'&&/^[\w-]{10,160}$/.test(r.fileId||'')&&extension(r.mimeType);}).slice(0,2):[];}catch(e){return [];}}
function transient(message,session){return (session&&session[message.title]||svgImages(message.text)).map(validateImage);}
function referenceFields(title,file,tags,chatTitle,messageTitle){
  if(!/^[\w-]{10,160}$/.test(file.id||'')||!extension(file.mimeType))throw Error('Drev returnerede ikke en gyldig billedreference.');
  return {title:title,caption:title,type:'text/vnd.tiddlywiki',text:'<$huwiki-ai-image source=<<currentTiddler>>/>\n\n[ext[Åbn på Drev|https://drive.google.com/file/d/'+file.id+'/view]]',
    tags:tags,'av-file-id':file.id,'av-url':file.url,'av-mime':file.mimeType,
    'ai-source-chat':chatTitle,'ai-source-message':messageTitle,'ai-created-by':'HUWiki AI',created:new Date(),modified:new Date()};
}
function rpc(wiki,method,args){
  return new Promise(function(resolve,reject){
    if(typeof google==='undefined'||!google.script||!google.script.run)return reject(Error(aiUi.text('Åbn wikien fra HUWiki for at gemme billeder i AV.')));
    var id=wiki.getTiddlerText('$:/Wiki/CurrentWikiId','');if(!id)return reject(Error('Den aktuelle wiki mangler et id.'));
    var runner=google.script.run.withSuccessHandler(resolve).withFailureHandler(reject);
    var parameters=method==='huApproveAvConsent'?[id].concat(args||[]):(args||[]).concat([id]);
    runner[method].apply(runner,parameters);
  });
}
function drawImages(w,parent,message,el,btn){
  var refs=references(message),images=transient(message,w.outputImages);
  if(!refs.length&&!images.length&&message.outputImageCount)el(parent,'p','huw-ai-warning',aiUi.text('Billedforslaget blev ikke gemt i AV før genindlæsning. Samtaleteksten er bevaret. En ny billedgenerering bruger et nyt API-kald.'));
  if(refs.length){refs.forEach(function(ref){var card=el(parent,'div','huw-ai-output-image');
    var img=el(card,'img');img.alt=ref.title;var status=el(card,'p','huwiki-ai-help',aiUi.text('Henter fra AV…'));
    function load(){loadAvImage($tw.wiki,ref).then(function(url){img.src=url;status.textContent=aiUi.text('Gemt i AV.');},function(e){status.textContent=e.message||String(e);});}load();
    btn(card,aiUi.text('Hent billede igen'),load,'huw-ai-secondary');
    btn(card,aiUi.text('Åbn billedtiddler'),function(){w.dispatchEvent({type:'tm-navigate',navigateTo:ref.title});},'huw-ai-secondary');
  });}
  images.forEach(function(image,index){if(refs.some(function(r){return r.index===index;}))return;var card=el(parent,'div','huw-ai-output-image');var img=el(card,'img');img.src=dataUrl(image);img.alt=aiUi.text('Billedforslag fra AI');
    btn(card,aiUi.text('Gem billede i AV…'),function(){w.openImageDialog(message,image,index);},'huw-ai-secondary');
    el(card,'p','huwiki-ai-help',aiUi.text('Billedforslag. Gem i AV for at beholde billedfilen.'));
  });
}
function drawDialog(w,root,el,btn,field){
  var d=w.tiddlerDialog,card=el(root,'section','huwiki-ai-card huw-ai-tiddler-dialog'),image=validateImage(d.image);
  el(card,'h3',null,aiUi.text('Gem billede i AV'));el(card,'p','huwiki-ai-help',aiUi.text('Filen gemmes i denne wikis AV-mappe. Tiddleren indeholder en reference til filen.'));
  var preview=el(card,'img','huw-ai-image-save-preview');preview.src=dataUrl(image);preview.alt=aiUi.text('Billedet der gemmes');
  field(card,aiUi.text('Titel'),d.title,function(v){d.title=v;});field(card,aiUi.text('Tags (adskilt med komma)'),d.tags,function(v){d.tags=v;});
  if(d.consent&&!d.consent.approved){
    el(card,'p','huw-ai-note',aiUi.text('AV-filen deles med wikiens ejer og redaktører: ')+(d.consent.recipients||[]).join(', '));
    var consent=el(card,'label','huw-ai-select-piece'),check=el(consent,'input');check.type='checkbox';check.checked=!!d.approved;
    check.addEventListener('change',function(){d.approved=check.checked;w.draw();});el(consent,'span',null,aiUi.text('Jeg godkender den viste AV-deling.'));
  }
  if(d.error)el(card,'p','huw-ai-warning',d.error);
  btn(card,d.saving?aiUi.text('Gemmer…'):aiUi.text('Gem i AV og opret tiddler'),function(){
    if(d.saving)return;d.saving=true;d.error='';w.draw();
    var proposed=String(d.title||aiUi.text('AI-billede')).trim(),tags=String(d.tags||'').split(',').map(function(t){return t.trim();}).filter(Boolean);
    Promise.resolve().then(function(){
      if(!proposed||proposed.indexOf('$:/')===0||/[\x00-\x1f]/.test(proposed))throw Error(aiUi.text('Vælg en almindelig tiddlertitel.'));
      return rpc($tw.wiki,'huGetAvConsent');
    }).then(function(c){
      if(!c.approved){
        if(!d.approved||!d.consent||d.consent.audience!==c.audience){d.consent=c;d.approved=false;throw Error(aiUi.text('Godkend først den viste AV-deling.'));}
        return rpc($tw.wiki,'huApproveAvConsent',[c.audience]);
      }
    }).then(function(){
      var base64=image.mimeType==='image/svg+xml'?btoa(unescape(encodeURIComponent(image.data))):image.data;
      return rpc($tw.wiki,'huSaveAvMedia',[{requestId:d.requestId,name:proposed.replace(/[\\/]/g,'-')+'.'+extension(image.mimeType),mimeType:image.mimeType,base64:base64}]);
    }).then(function(file){
      var current=$tw.wiki.getTiddler(d.message.title);if(!current)throw Error(aiUi.text('Samtalebeskeden findes ikke længere. Billedfilen er gemt i AV.'));
      var title=proposed,n=2;while($tw.wiki.getTiddler(title))title=proposed+' ('+(n++)+')';
      cacheImage(file.id,image);
      $tw.wiki.addTiddler(new $tw.Tiddler(referenceFields(title,file,tags,d.chatTitle,d.message.title)));
      var refs=references({imageRefs:current.fields['ai-images']}).filter(function(r){return r.index!==d.imageIndex;});refs.push({title:title,fileId:file.id,mimeType:file.mimeType,index:d.imageIndex});
      $tw.wiki.addTiddler(new $tw.Tiddler(current,{'ai-images':JSON.stringify(refs),modified:new Date()}));
      w.tiddlerDialog=null;w.message(aiUi.text('Billedfilen er gemt i AV, og billedtiddleren er oprettet.'),false);
      w.dispatchEvent({type:'tm-navigate',navigateTo:title});
    }).catch(function(e){d.saving=false;d.error=e.message||String(e);w.draw();});
  },'huw-ai-primary').disabled=!!d.saving||(d.consent&&!d.consent.approved&&!d.approved);
  btn(card,aiUi.text('Gem som tekst / kode i stedet'),function(){w.tiddlerDialog=null;w.openTiddlerDialog(d.message,true);},'huw-ai-secondary').disabled=!!d.saving;
  btn(card,aiUi.text('Annullér'),function(){w.tiddlerDialog=null;w.draw();},'huw-ai-secondary').disabled=!!d.saving;
}
exports.safeSvg=safeSvg;exports.validateImage=validateImage;exports.svgImages=svgImages;exports.dataUrl=dataUrl;
exports.references=references;exports.transient=transient;exports.referenceFields=referenceFields;
exports.drawImages=drawImages;exports.drawDialog=drawDialog;
exports.loadAvImage=loadAvImage;
})();
